// ============================================
// VALIDATION INPUT (RFC-004)
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Extract Tenant ID ---
const tenantId = headers['x-tenant-id'] 
  || headers['X-Tenant-ID'] 
  || headers['X-Tenant-Id']
  || $env.DEFAULT_TENANT_ID
  || 'default';

// --- Validation required fields ---
if (!body.discord_user_id) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le champ "discord_user_id" est requis',
    http_status: 400
  };
}

if (!body.guild_id) {
  return {
    error: true,
    error_code: 'MISSING_GUILD_ID',
    message: 'Le champ "guild_id" est requis',
    http_status: 400
  };
}

if (!body.old_channel_id) {
  return {
    error: true,
    error_code: 'MISSING_OLD_CHANNEL_ID',
    message: 'Le champ "old_channel_id" est requis',
    http_status: 400
  };
}

if (!body.bot_token) {
  return {
    error: true,
    error_code: 'MISSING_BOT_TOKEN',
    message: 'Le champ "bot_token" est requis',
    http_status: 400
  };
}

// --- Return validated data ---
return {
  error: false,
  data: {
    discord_user_id: body.discord_user_id,
    guild_id: body.guild_id,
    old_channel_id: body.old_channel_id,
    bot_token: body.bot_token,
    channel_type: body.channel_type || 'support',
    category_id: body.category_id || null,
    tenant_id: tenantId,
    metadata: {
      ...body.metadata,
      recreated_from: body.old_channel_id,
      reason: 'unknown_channel_error'
    }
  }
};

// ============================================
// FORMAT RECREATED CHANNEL RESPONSE
// ============================================

const apiResponse = $input.first().json;
const channelData = apiResponse.data || apiResponse;
const oldChannelId = $('Validate Input').first().json.data.old_channel_id;

return {
  success: true,
  status: 'recreated',
  channel: {
    channel_id: channelData.channel_id,
    channel_type: channelData.channel_type,
    channel_name: channelData.channel_name,
    is_active: channelData.is_active
  },
  previous_channel_id: oldChannelId
};

// ============================================
// FORMAT VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation'
  },
  http_status: input.http_status || 400
};

// ============================================
// FORMAT DISCORD API ERROR
// ============================================

const input = $input.first().json;

// Discord API error codes
const discordCode = input.code;
let httpStatus = 500;
let errorCode = 'DISCORD_ERROR';
let message = input.message || 'Erreur Discord API';

switch(discordCode) {
  case 50001: // Missing Access
    httpStatus = 403;
    errorCode = 'MISSING_ACCESS';
    message = 'Le bot n\'a pas accès à ce serveur';
    break;
  case 50013: // Missing Permissions
    httpStatus = 403;
    errorCode = 'MISSING_PERMISSIONS';
    message = 'Le bot n\'a pas les permissions pour créer un channel';
    break;
  case 10004: // Unknown Guild
    httpStatus = 404;
    errorCode = 'GUILD_NOT_FOUND';
    message = 'Serveur Discord non trouvé';
    break;
  case 10013: // Unknown User
    httpStatus = 404;
    errorCode = 'USER_NOT_FOUND';
    message = 'Utilisateur Discord non trouvé';
    break;
  case 30013: // Maximum channels reached
    httpStatus = 400;
    errorCode = 'MAX_CHANNELS';
    message = 'Nombre maximum de channels atteint sur ce serveur';
    break;
  default:
    if (input.error) {
      message = input.error;
    }
}

return {
  success: false,
  error: {
    code: errorCode,
    message: message,
    discord_code: discordCode
  },
  http_status: httpStatus
};
